CREATE TEMPORARY VIEW platform_benchmark_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(is_ads IS NOT NULL, CAST(is_ads AS STRING), 'false') AS is_ads
    ,CASE
        WHEN keyword IS NULL OR keyword = '' THEN 'false'
        ELSE 'true'
    END AS with_keyword
    ,CASE
        WHEN sort_type = 'relevancy' THEN ARRAY(sort_type, '__ALL__')
        ELSE ARRAY('__ALL__')
    END AS sort_types
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', ARRAY(TRIM(LOWER(search_entrance)), '__ALL__'), ARRAY('__ALL__')) AS search_entrances
    ,CASE
        WHEN search_mid LIKE 'image%' THEN ARRAY(search_mid, 'multimodal_search_all', '__ALL__')
        ELSE IF(search_mid IS NOT NULL AND TRIM(LOWER(search_mid)) != '', ARRAY(TRIM(LOWER(search_mid)), 'text_search_all', '__ALL__'), ARRAY('text_search_all', '__ALL__'))
    END AS search_mids
    ,CASE
        WHEN page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND page_section IS NULL AND target_type IN ('item', 'video', 'livestream') THEN ARRAY(target_type, 'item+video+live', '__ALL__')
        ELSE ARRAY('__ALL__')
    END AS target_types
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_platform_user_item_keyword_benchmark_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
    AND (ARRAY_CONTAINS(scenario_tags, 'dpm module Global Search business line Search'))
GROUP BY 
    1,2,3,4,5,6,7;

--sql_divide_splitter--

CREATE TEMPORARY VIEW platform_benchmark_user_agg_${grass_region_without_quote} AS
SELECT
    user_id
    ,sort_type
    ,IF(GROUPING(is_ads) = 1, '__ALL__', is_ads) AS is_ads
    ,search_entrance
    ,search_mid
    ,IF(GROUPING(with_keyword) = 1, '__ALL__', with_keyword) AS with_keyword
    ,card_type 

    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,power(sum(order_cnt), 2) AS squared_user_order_sum
    ,CASE WHEN SUM(order_cnt) > 0 THEN SUM(gmv) / SUM(order_cnt) ELSE 0 END AS abs
FROM
    platform_benchmark_raw_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(search_mids) AS search_mid
    LATERAL VIEW EXPLODE(target_types) AS card_type
    LATERAL VIEW EXPLODE(sort_types) AS sort_type
    LATERAL VIEW EXPLODE(search_entrances) AS search_entrance
GROUP BY
    user_id
    ,search_mid
    ,card_type
    ,sort_type
    ,search_entrance
    ,CUBE(is_ads, with_keyword);

