CREATE TEMPORARY VIEW srp_search_${grass_region_without_quote} AS
SELECT
    user_id
    ,if(sort_type IS NOT NULL, cast(sort_type AS STRING), 'NA') AS sort_type
    ,device_id
    ,trim(lower(keyword)) AS keyword
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,CASE
        WHEN search_mid LIKE 'image%' THEN ARRAY(search_mid, 'multimodal_search_all', '__ALL__')
        ELSE IF(search_mid IS NOT NULL AND TRIM(LOWER(search_mid)) != '', ARRAY(TRIM(LOWER(search_mid)), 'text_search_all',  '__ALL__'), ARRAY('text_search_all', '__ALL__'))
    END AS search_mids
    ,SUM(IF(view_cnt > 0, view_cnt, NULL)) AS search_cnt
    ,SUM(IF(view_not_back_cnt > 0, view_not_back_cnt, NULL)) AS view_no_back_cnt
    ,SUM(IF(ppv_cnt > 0 AND target_type = 'item' AND page_section IS NULL, 1, NULL)) AS search_success_cnt
    ,SUM(IF(imp_cnt > 0 AND target_type = 'no_recall_general', 1, NULL)) AS search_non_result_cnt
    ,SUM(IF(click_cnt > 0 AND target_type IN ('item', 'video', 'livestream')  AND page_section IS NULL, 1, NULL)) AS direct_search_success_cnt
    ,SUM(IF(click_cnt > 0  AND (
        (target_type IN ('item','video','livestream', 'curated_search', 'live_stream_floating_preview') AND page_section IS NULL
            ) OR ((target_type LIKE 'shop%' OR target_type LIKE 'creator%') AND page_section IS NULL
            ) OR (page_section = 'creator')
    ), 1, NULL)) AS broad_search_success_cnt
FROM
    srdi_mart.dws_sr_data_warehouse_platform_user_item_keyword_benchmark_1d
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
GROUP BY 1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_volume_${grass_region_without_quote} AS 
SELECT
    user_id 
    ,IF(GROUPING(search_entrance) = 1, '__ALL__', search_entrance) AS search_entrance
    ,search_mid
    ,IF(GROUPING(sort_type) = 1, '__ALL__', sort_type) AS sort_type

    ,SUM(search_cnt) AS view_cnt
    ,SUM(view_no_back_cnt) AS view_no_back_cnt
    ,COUNT(DISTINCT CASE WHEN search_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS search_volume
    ,COUNT(DISTINCT CASE WHEN search_success_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS search_success_volume
    ,COUNT(DISTINCT CASE WHEN search_non_result_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS search_non_result_volume
    ,COUNT(DISTINCT CASE WHEN direct_search_success_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS direct_search_success_volume
    ,COUNT(DISTINCT CASE WHEN broad_search_success_cnt > 0 THEN (device_id, keyword) ELSE NULL END) AS broad_search_success_volume
FROM 
    srp_search_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(search_mids) AS search_mid
GROUP BY
    user_id
    ,search_mid 
    ,CUBE(search_entrance,sort_type);

--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_search_volumn_${grass_region_without_quote} AS 
SELECT
    exp_group_id
    ,search_entrance
    ,search_mid
    ,sort_type
    
    ,SUM(view_cnt) AS view_cnt
    ,SUM(view_no_back_cnt) AS view_no_back_cnt
    ,SUM(IF(view_cnt > 0, 1, NULL)) AS search_uu
    ,sum(search_volume) AS search_volume
    ,sum(search_success_volume) AS search_success_result_volume
    ,sum(search_non_result_volume) AS search_non_result_volume
    ,sum(direct_search_success_volume) AS direct_search_success_volume
    ,sum(broad_search_success_volume) AS broad_search_success_volume
FROM
    search_volume_${grass_region_without_quote} dws_search_volumn
    INNER JOIN user_exp_mapping_1d_${grass_region_without_quote} user_exp
    ON user_exp.user_id = dws_search_volumn.user_id
GROUP BY 
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW multimodal_metrics_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,IF(search_mid IS NOT NULL AND TRIM(LOWER(search_mid)) != '', TRIM(LOWER(search_mid)), 'NA') AS search_mid
    ,CASE
        WHEN keyword IS NULL OR TRIM(LOWER(keyword)) = '' THEN 'false'
        ELSE 'true'
    END AS with_keyword
    ,device_id
    ,keyword
    ,GET_JSON_OBJECT(ai_search_info, '$.md5') AS md5
    ,TRANSFORM(
        array('left', 'top', 'width', 'height')
        ,key -> cast(GET_JSON_OBJECT(ai_search_info, concat('$.box.box_xy.', key)) AS INT)
    ) AS box_xy
    ,SUM(IF(operation = 'view' AND original_page_type = 'search', 1, NULL)) AS search_cnt -- View operations does not have reporting_module/business_line
    ,SUM(IF(operation = 'click' AND reporting_module = 'Global Search' AND reporting_business_line = 'Search'
        AND target_type IN ('item', 'video', 'livestream'), 1, NULL)) AS direct_search_success_cnt
    ,SUM(IF(operation = 'click' AND reporting_module = 'Global Search' AND reporting_business_line = 'Search' AND (
        (target_type IN ('item','video','livestream', 'curated_search', 'live_stream_floating_preview') AND page_section IS NULL)
        OR ((target_type like 'shop%' or target_type like 'creator%') AND page_section IS NULL)
        OR (page_section[0] = 'creator')
    ), 1, NULL)) AS broad_search_success_cnt
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation IN ('view', 'click')
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND GET_JSON_OBJECT(ai_search_info, '$.md5') != ''
    AND search_mid LIKE 'image%'
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW multimodal_metrics_user_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(GROUPING(search_entrance) = 1, '__ALL__', search_entrance) AS search_entrance
    ,IF(GROUPING(search_mid) = 1, 'multimodal_search_all', search_mid) AS search_mid
    ,IF(GROUPING(with_keyword) = 1, '__ALL__', with_keyword) AS with_keyword
    ,COUNT(DISTINCT CASE WHEN search_cnt > 0 THEN (device_id, keyword, md5) ELSE NULL END) AS ms_search_volume
    ,COUNT(DISTINCT CASE WHEN direct_search_success_cnt > 0 THEN (device_id, keyword, md5) ELSE NULL END) AS ms_direct_search_success_volume
    ,COUNT(DISTINCT CASE WHEN broad_search_success_cnt > 0 THEN (device_id, keyword, md5) ELSE NULL END) AS ms_broad_search_success_volume
    ,COUNT(DISTINCT CASE WHEN search_cnt > 0 THEN (device_id, keyword, md5, box_xy) ELSE NULL END) AS ms_search_volume_v2
    ,COUNT(DISTINCT CASE WHEN direct_search_success_cnt > 0 THEN (device_id, keyword, md5, box_xy) ELSE NULL END) AS ms_direct_search_success_volume_v2
    ,COUNT(DISTINCT CASE WHEN broad_search_success_cnt > 0 THEN (device_id, keyword, md5, box_xy) ELSE NULL END) AS ms_broad_search_success_volume_v2
FROM
    multimodal_metrics_raw_${grass_region_without_quote}
GROUP BY
    user_id, CUBE(search_entrance, search_mid, with_keyword);

--sql_divide_splitter--

CREATE TEMPORARY VIEW multimodal_exp_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,search_entrance
    ,search_mid
    ,with_keyword
    ,SUM(ms_search_volume) AS ms_search_volume
    ,SUM(ms_direct_search_success_volume) AS ms_direct_search_success_volume
    ,SUM(ms_broad_search_success_volume) AS ms_broad_search_success_volume
    ,SUM(ms_search_volume_v2) AS ms_search_volume_v2
    ,SUM(ms_direct_search_success_volume_v2) AS ms_direct_search_success_volume_v2
    ,SUM(ms_broad_search_success_volume_v2) AS ms_broad_search_success_volume_v2
FROM
    multimodal_metrics_user_grouped_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3,4;

