WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
    AND page_type IN (
        'global_search'
        ,'search_in_mall'
        ,'search_in_microsite'
        ,'search_in_main_category'
        ,'collection'
        ,'search_in_others'
        ,'search_in_collection'
        ,'search_in_product_attribute'
        ,'main_category_browsing'
        ,'search_in_voucher'
        ,'search_in_subcategory'
        ,'search_in_pdp'
        ,'search_prefill'
        ,'search'
    )
    AND page_section IS NULL
    AND target_type IN ('item','video','livestream','related_search')
