CREATE TEMPORARY VIEW search_srp_user_benchmark_views_${grass_region_without_quote} AS
SELECT
    user_id
    ,ARRAY(search_entrance, '__ALL__') AS search_entrance
    ,CASE
        WHEN search_mid LIKE 'image%' THEN ARRAY(search_mid, 'multimodal_search_all', '__ALL__')
        ELSE IF(search_mid IS NOT NULL AND TRIM(LOWER(search_mid)) != '', ARRAY(TRIM(LOWER(search_mid)), 'text_search_all', '__ALL__'), ARRAY('text_search_all', '__ALL__'))
    END AS search_mid
    ,CASE
        WHEN keyword IS NULL OR keyword = '' THEN ARRAY('false', '__ALL__')
        ELSE ARRAY('true', '__ALL__')
    END AS with_keyword
    ,local_date
FROM
    srdi_mart.dws_sr_data_warehouse_search_srp_user_benchmark_1d
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 29) AND ${local_date}
    AND user_id > 0
    AND view_cnt > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
GROUP BY
    1,2,3,4,5;

