SELECT
    exp_group_id
    ,a.user_id AS user_id
    ,search_entrance_group AS search_entrance
    ,search_mid_group AS search_mid
    ,with_keyword_group AS with_keyword
    ,MAX(IF(a.local_date = ${local_date}, TRUE, FALSE)) AS is_0d_user
    ,MAX(IF(a.local_date = DATE_SUB(${local_date}, 1), TRUE, FALSE)) AS is_1d_user
    ,MAX(IF(a.local_date = DATE_SUB(${local_date}, 7), TRUE, FALSE)) AS is_7d_user
FROM
    search_srp_user_benchmark_views_${grass_region_without_quote} a
JOIN
    user_exp_mapping_30d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
LATERAL VIEW
    EXPLODE(search_entrance) AS search_entrance_group
LATERAL VIEW
    EXPLODE(search_mid) AS search_mid_group
LATERAL VIEW
    EXPLODE(with_keyword) AS with_keyword_group
GROUP BY
    1,2,3,4,5;

