CREATE TEMPORARY VIEW retention_exp_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,search_entrance
    ,search_mid
    ,with_keyword
    ,SUM(IF(is_1d_user = TRUE, 1, 0)) AS search_uu_1d
    ,SUM(IF(is_0d_user = TRUE AND is_1d_user = TRUE, 1, 0)) AS retention_uu_1d
    ,SUM(IF(is_7d_user = TRUE, 1, 0)) AS search_uu_7d
    ,SUM(IF(is_0d_user = TRUE AND is_7d_user = TRUE, 1, 0)) AS retention_uu_7d
    ,COUNT(1) AS month_dau
FROM
    retention_exp_user_level_metrics_${grass_region_without_quote}
GROUP BY
    1,2,3,4;

