CREATE TEMPORARY VIEW gmv995_v2_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(is_ads IS NOT NULL, CAST(is_ads AS STRING), 'false') AS is_ads
    ,CASE
        WHEN keyword IS NULL OR keyword = '' THEN 'false'
        ELSE 'true'
    END AS with_keyword
    ,CASE
        WHEN sort_type = 'relevancy' THEN ARRAY(sort_type, '__ALL__')
        ELSE ARRAY('__ALL__')
    END AS sort_types
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', ARRAY(TRIM(LOWER(search_entrance)), '__ALL__'), ARRAY('__ALL__')) AS search_entrances
    ,CASE
        WHEN search_mid LIKE 'image%' THEN ARRAY(search_mid, 'multimodal_search_all', '__ALL__')
        ELSE IF(search_mid IS NOT NULL AND TRIM(LOWER(search_mid)) != '', ARRAY(TRIM(LOWER(search_mid)), 'text_search_all', '__ALL__'), ARRAY('text_search_all', '__ALL__'))
    END AS search_mids
    ,CASE
        WHEN page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND page_section IS NULL AND target_type IN ('item', 'video', 'livestream') THEN ARRAY(target_type, 'item+video+live', '__ALL__')
        ELSE ARRAY('__ALL__')
    END AS target_types
    ,order_id
    ,item_id
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_platform_order_benchmark_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
    AND (ARRAY_CONTAINS(scenario_tags, 'dpm module Global Search business line Search'))
GROUP BY 
    1,2,3,4,5,6,7,8,9;

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_item_order_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,sort_type
    ,IF(GROUPING(is_ads) = 1, '__ALL__', is_ads) AS is_ads
    ,search_entrance
    ,search_mid
    ,IF(GROUPING(with_keyword) = 1, '__ALL__', with_keyword) AS with_keyword
    ,card_type
    ,order_id
    ,a.item_id AS item_id
    ,COALESCE(category_tag, 'low gmv') AS category_tag
    ,COALESCE(SUM(order_cnt), 0.0) AS order_cnt
    ,COALESCE(SUM(gmv), 0.0) AS gmv
    ,COALESCE(SUM(pc2_gmv), 0.0) AS pc2_gmv
FROM
    gmv995_v2_raw_${grass_region_without_quote} a
LEFT JOIN
    srdi_mart.dim_sr_data_warehouse_item b
ON
    a.item_id = b.item_id
    AND b.grass_region = ${grass_region}
    AND b.local_date = ${local_date}
LATERAL VIEW
    EXPLODE(search_mids) AS search_mid
LATERAL VIEW
    EXPLODE(target_types) AS card_type
LATERAL VIEW
    EXPLODE(sort_types) AS sort_type
LATERAL VIEW
    EXPLODE(search_entrances) AS search_entrance
GROUP BY
    user_id
    ,search_mid
    ,card_type
    ,sort_type
    ,search_entrance
    ,CUBE(is_ads, with_keyword)
    ,order_id
    ,a.item_id
    ,category_tag;

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_outlier_${grass_region_without_quote} AS
SELECT
    is_ads
    ,category_tag
    ,gmv_995pct
    ,pc2_gmv_995pct
FROM 
    srdi_mart.dim_sr_data_warehouse_category_gmv_outlier
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND feature_group = 'dpm module Global Search business line Search';

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_user_level_filtered_${grass_region_without_quote} AS
SELECT
    user_id
    ,sort_type
    ,a.is_ads AS is_ads
    ,search_entrance
    ,search_mid
    ,with_keyword
    ,card_type
    ,a.category_tag AS category_tag
    ,SUM(IF(gmv <= gmv_995pct, order_cnt, 0)) AS gmv_order_cnt_995_v2
    ,SUM(IF(gmv <= gmv_995pct, gmv, gmv_995pct)) AS gmv_995_v2
    ,SUM(IF(pc2_gmv <= pc2_gmv_995pct, pc2_gmv, pc2_gmv_995pct)) AS pc2_gmv_995_v2
FROM
    gmv995_v2_item_order_grouped_${grass_region_without_quote} a
LEFT JOIN
    gmv995_v2_outlier_${grass_region_without_quote} b
ON
    a.is_ads = b.is_ads
    AND a.category_tag = b.category_tag
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_exp_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,sort_type
    ,is_ads
    ,search_entrance
    ,search_mid
    ,with_keyword
    ,card_type
    ,SUM(IF(category_tag = 'high gmv', gmv_order_cnt_995_v2, NULL)) AS high_gmv_order_cnt_995_v2
    ,SUM(IF(category_tag = 'high gmv', gmv_995_v2, NULL)) AS high_gmv_995_v2
    ,SUM(IF(category_tag = 'high gmv', pc2_gmv_995_v2, NULL)) AS high_pc2_gmv_995_v2
    ,SUM(IF(category_tag = 'low gmv', gmv_order_cnt_995_v2, NULL)) AS low_gmv_order_cnt_995_v2
    ,SUM(IF(category_tag = 'low gmv', gmv_995_v2, NULL)) AS low_gmv_995_v2
    ,SUM(IF(category_tag = 'low gmv', pc2_gmv_995_v2, NULL)) AS low_pc2_gmv_995_v2
FROM
    gmv995_v2_user_level_filtered_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3,4,5,6,7;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_entrance_mid_metrics_v2_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
/*+ REPARTITION(200) */
    experiment_id
    ,a.exp_group_id AS exp_group_id
    ,a.sort_type AS sort_type
    ,a.is_ads AS is_ads
    ,a.search_entrance AS search_entrance
    ,a.search_mid AS search_mid
    ,a.with_keyword AS with_keyword
    ,a.card_type

    ,exp_group_uu
    ,imp_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
    ,click_uu / imp_uu AS ctr_uu
    ,click_cnt / imp_cnt AS ctr
    ,ppv_cnt
    ,ppv_uu
    ,cart_cnt
    ,cart_uu
    ,order_cnt
    ,squared_user_order_sum
    ,order_uu
    ,gmv
    ,pc2_gmv
    ,gmv_995
    ,pc2_gmv_995
    ,gmv_uu_995
    ,pc2_gmv_uu_995

    ,view_cnt AS srp_pv_cnt
    ,view_no_back_cnt AS srp_pv_not_back_cnt
    ,search_uu AS search_dau
    ,search_volume
    ,search_success_result_volume
    ,search_non_result_volume
    ,direct_search_success_volume
    ,broad_search_success_volume
    ,ms_search_volume
    ,ms_direct_search_success_volume
    ,ms_broad_search_success_volume

    ,ads_revenue
    ,ads_load_numerator / ads_load_denominator AS ads_load

    ,max_imp_location_avg
    ,max_imp_location_p50
    ,first_click_location_avg
    ,first_click_location_p50
    ,search_uu_1d
    ,retention_uu_1d
    ,search_uu_7d
    ,retention_uu_7d

    ,high_gmv_order_cnt_995_v2
    ,high_gmv_995_v2
    ,high_pc2_gmv_995_v2
    ,low_gmv_order_cnt_995_v2
    ,low_gmv_995_v2
    ,low_pc2_gmv_995_v2

    ,month_dau
    ,top20_ads_load_numerator / top20_ads_load_denominator AS top20_ads_load
    ,ms_search_volume_v2
    ,ms_direct_search_success_volume_v2
    ,ms_broad_search_success_volume_v2
FROM
    search_exp_metrics_${grass_region_without_quote} a
LEFT JOIN
    exp_uu_count_${grass_region_without_quote} b
ON
    a.exp_group_id = b.exp_group_id
LEFT JOIN dim_exp_${grass_region_without_quote} i 
ON
    a.exp_group_id = i.exp_group_id
LEFT JOIN
    ads_exp_metrics_${grass_region_without_quote} c
ON
    a.exp_group_id = c.exp_group_id
    AND a.sort_type = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.search_entrance = c.search_entrance
    AND a.search_mid = c.search_mid
    AND a.with_keyword = c.with_keyword
    AND a.card_type = '__ALL__'
LEFT JOIN
    ads_exp_denominator_metrics_${grass_region_without_quote} k
ON
    a.exp_group_id = k.exp_group_id
    AND a.sort_type = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.search_entrance = k.search_entrance
    AND a.search_mid = k.search_mid
    AND a.with_keyword = k.with_keyword
    AND a.card_type = '__ALL__'
LEFT JOIN 
    exp_search_volumn_${grass_region_without_quote} d 
ON
    a.exp_group_id = d.exp_group_id
    AND a.sort_type = d.sort_type
    AND a.is_ads = '__ALL__'
    AND a.search_entrance = d.search_entrance
    AND a.search_mid = d.search_mid
    AND a.with_keyword = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    multimodal_exp_metrics_${grass_region_without_quote} e
ON
    a.exp_group_id = e.exp_group_id
    AND a.sort_type = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.search_entrance = e.search_entrance
    AND a.search_mid = e.search_mid
    AND a.with_keyword = e.with_keyword
    AND a.card_type = '__ALL__'
LEFT JOIN
    max_imp_location_exp_metrics_${grass_region_without_quote} f
ON
    a.exp_group_id = f.exp_group_id
    AND a.sort_type = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.search_entrance = f.search_entrance
    AND a.search_mid = f.search_mid
    AND a.with_keyword = f.with_keyword
    AND a.card_type = '__ALL__'
LEFT JOIN
    first_click_location_exp_metrics_${grass_region_without_quote} g
ON
    a.exp_group_id = g.exp_group_id
    AND a.sort_type = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.search_entrance = g.search_entrance
    AND a.search_mid = g.search_mid
    AND a.with_keyword = g.with_keyword
    AND a.card_type = '__ALL__'
LEFT JOIN
    retention_exp_metrics_${grass_region_without_quote} h
ON
    a.exp_group_id = h.exp_group_id
    AND a.sort_type = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.search_entrance = h.search_entrance
    AND a.search_mid = h.search_mid
    AND a.with_keyword = h.with_keyword
    AND a.card_type = '__ALL__'
LEFT JOIN
    gmv995_v2_exp_metrics_${grass_region_without_quote} j
ON
    a.exp_group_id = j.exp_group_id
    AND a.sort_type = j.sort_type
    AND a.is_ads = j.is_ads
    AND a.search_entrance = j.search_entrance
    AND a.search_mid = j.search_mid
    AND a.with_keyword = j.with_keyword
    AND a.card_type = j.card_type;
